/// <summary>
/// Populate the ISDAppIntgDMFIntegrationImportPerfChart temp table which backs the ISDAppIntgDMFIntegrationImportPerfChart
/// </summary>
/// <param name = "_category">The filter for the chart</param>
/// <returns>Populated ISDAppIntgDMFIntegrationImportPerfChart table buffer</returns>
public ISDAppIntgDMFIntegrationImportPerfChart populateData(DMFExecutionHistoryDateFilterOptions _category = DMFExecutionHistoryDateFilterOptions::Past3Days)
{
    DMFDefinitionGroupExecution                 definitionGroupExecution;
    DMFEntity                                   entity;
    DMFDefinitionGroup                          definitionGroup;
    utcdatetime                                 filterDateTime = this.getfilterDateTime(_category);

    //This is here because when the user changes the drop down filter for the chart, the same instance of the temp table is
    //used.  This will clear out the existing values so the new ones can be inserted.
    delete_from this;
    ISDAppIntgDMFIntegrationImportPerfChart     chartTable;
    chartTable.linkPhysicalTableInstance(this);

    while select DefinitionGroupName from definitionGroup
        where definitionGroup.OperationType == DMFOperationType::Import
        && definitionGroup.ProjectCategory == DMFProjectCategory::Integration
    {

        chartTable.DefGroupName =  definitionGroup.DefinitionGroupName;

        //Source to staging
        definitionGroupExecution.clear();
        select count(RecID) from definitionGroupExecution group by DefinitionGroup
            where definitionGroupExecution.DefinitionGroup == definitionGroup.DefinitionGroupName
            && definitionGroupExecution.CreatedDateTime > filterDateTime
            && definitionGroupExecution.StagingStatus == 3
                exists join entity
                    where entity.EntityName == definitionGroupExecution.Entity
                    && entity.ParentEntityName == '';

        chartTable.FailedJobImportToStaging = definitionGroupExecution.RecId;;

        //Staging to target
        definitionGroupExecution.clear();
        select count(RecID) from definitionGroupExecution group by DefinitionGroup
            where definitionGroupExecution.DefinitionGroup == definitionGroup.DefinitionGroupName
            && definitionGroupExecution.CreatedDateTime > filterDateTime
            && ((definitionGroupExecution.TargetStatus == 3) || (definitionGroupExecution.StagingErrorCount > 0) || (definitionGroupExecution.TargetErrorCount > 0))
                exists join entity
                    where entity.EntityName == definitionGroupExecution.Entity
                    && entity.ParentEntityName == '';

        chartTable.FailedJobStagingToTarget = definitionGroupExecution.RecId;

        //All completed jobs
        definitionGroupExecution.clear();
        select count(RecID) from definitionGroupExecution group by DefinitionGroup
            where definitionGroupExecution.DefinitionGroup == definitionGroup.DefinitionGroupName
            && definitionGroupExecution.CreatedDateTime > filterDateTime
            && definitionGroupExecution.StagingStatus == 4
            && definitionGroupExecution.TargetStatus == 4
                exists join entity
                    where entity.EntityName == definitionGroupExecution.Entity
                    && entity.ParentEntityName == '';

        chartTable.AllCompletedJob = definitionGroupExecution.RecId;

        chartTable.insert();
    }

    return chartTable;
}

public utcdatetime getfilterDateTime(DMFExecutionHistoryDateFilterOptions _category)
{
    utcdatetime filterDateTime;

    switch (_category)
    {
        case DMFExecutionHistoryDateFilterOptions::PastDay:
            filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1);
            break;

        case DMFExecutionHistoryDateFilterOptions::Past3Days:
            filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -3);
            break;

        case DMFExecutionHistoryDateFilterOptions::PastWeek:
            filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);
            break;

        case DMFExecutionHistoryDateFilterOptions::PastMonth:
            filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -1);
            break;

        case DMFExecutionHistoryDateFilterOptions::Past3Months:
            filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -3);
            break;

        case DMFExecutionHistoryDateFilterOptions::Past6Months:
            filterDateTime = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -6);
            break;

        case DMFExecutionHistoryDateFilterOptions::All:
            filterDateTime = DateTimeUtil::minValue();
            break;

        default:
            // Default: Last week to match selection on the standard view of workspace
            filterDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -7);
            break;
    }

    return filterDateTime;
}
